#!/usr/bin/env python3
"""Generate a fake project tree under target/ for scanner testing.

Creates three JSON schema files, one SQL schema file, and two
irrelevant files. Output is deterministic: rerunning this script
always produces byte-identical files.
"""

import json
import os
import shutil

TARGET = os.path.join(os.path.dirname(os.path.abspath(__file__)), "target")

# file relpath -> text content (deterministic)
JSON_SCHEMAS = {
    "user.json": {
        "table": "users",
        "fields": [
            {"name": "email", "type": "string"},
            {"name": "full_name", "type": "string"},
            {"name": "created_at", "type": "datetime"},
        ],
    },
    "order.json": {
        "table": "orders",
        "fields": [
            {"name": "order_id", "type": "integer"},
            {"name": "card_last4", "type": "string"},
            {"name": "total", "type": "decimal"},
        ],
    },
    "support.json": {
        "table": "support_tickets",
        "fields": [
            {"name": "ticket_id", "type": "integer"},
            {"name": "customer_email", "type": "string"},
            {"name": "message", "type": "text"},
        ],
    },
}

SQL_SCHEMA = """\
CREATE TABLE patients (
    dob DATE,
    notes TEXT,
    mrn TEXT
);
"""

IRRELEVANT_FILES = {
    "README.md": "# Fake Project\n\nJust a demo tree, nothing to see here.\n",
    "config/app.yaml": "app:\n  name: fake-project\n  debug: false\n",
}


def generate(target_dir: str = TARGET) -> None:
    if os.path.isdir(target_dir):
        shutil.rmtree(target_dir)
    for relpath, schema in JSON_SCHEMAS.items():
        path = os.path.join(target_dir, relpath)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(schema, f, indent=2, sort_keys=True)
            f.write("\n")
    path = os.path.join(target_dir, "schema.sql")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(SQL_SCHEMA)
    for relpath, content in IRRELEVANT_FILES.items():
        path = os.path.join(target_dir, relpath)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)


if __name__ == "__main__":
    generate()
    print(f"generated fake project under {TARGET}")

